window.products.push({"id":421597,"name":"SkyTech Manual On/Off Gas Valve Kit On/Off/Hi/Med/Lo Remote (AF-LMF-RVS)","category":"homeandappliances","retail price":359.25,"sale price":null,"image":"https://m.media-amazon.com/images/I/312jz2AqxOL._AC_.jpg","description":"The Skytech AF-LMF/RVS gas valve kit was developed to provide safe, reliable, user-friendly control for gas heating appliances. This safety pilot kit was designed to be used with 18 to 30-inch gas logs sets. The AF-LMF/RVS features manual On/Off gas valve with step motor and a flame modulating remote control with On/Off function and Hi/Med/Low flame control. It includes a complete pilot assembly with 30-millivolt thermocouple, On/Off remote control, damper clamp, and all connectors for the main burner and pilot. The kit is for use with natural gas (NG) vented logs. An optional LP conversion kit is available and sold separately.","images":["https://m.media-amazon.com/images/I/312jz2AqxOL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"SkyTech","source_asin":"B005EGR2VU","category_path":"Home & Kitchen"},"sku":"BM-421597","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B005EGR2VU","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B005EGR2VU","price_pending":true,"merchant_ready":false});
